'use strict';

const fs = require('fs');
const input = fs.readFileSync(0, 'utf8').trim().split(/\s+/).map(Number);

const n = input[0];
const heights = input.slice(1, n + 1);

for (let i = 1; i < n; i++) {
  heights[i] = Math.min(heights[i], heights[i - 1] + 1);
}

for (let i = n - 2; i >= 0; i--) {
  heights[i] = Math.min(heights[i], heights[i + 1] + 1);
}

console.log(heights.join(' '));
